using eaf2apt;
using System;
namespace BinaryAssetBuilder.UiCompiler
{
    internal static class TextureBuilder
    {
        // StandardTexture / A8R8G8B8 / one mip, the exact route generated by ARSDK2.
        internal static byte[] Dds(MemoryTexture texture)
        {
            var data = new byte[checked(128 + texture.Pixels.Length)];
            data[0] = (byte)'D'; data[1] = (byte)'D'; data[2] = (byte)'S'; data[3] = 32;
            void W(int at, uint value) => CompiledUiAsset.Word(data, at, value);
            W(4, 124); W(8, 0x100f); W(12, (uint)texture.Height); W(16, (uint)texture.Width); W(20, (uint)texture.Width * 4); W(28, 1);
            W(76, 32); W(80, 0x41); W(88, 32); W(92, 0xff0000); W(96, 0xff00); W(100, 0xff); W(104, 0xff000000); W(108, 0x1000);
            Buffer.BlockCopy(texture.Pixels, 0, data, 128, texture.Pixels.Length); return data;
        }
    }
}
